'use strict';
let alternativeRequest=0;
const resultMoney=value=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',minimumFractionDigits:0,maximumFractionDigits:2}).format(value/100);
function deltaLabel(value){return value===null?'Нет полной корзины':value===0?'Без изменения суммы':(value>0?'+':'-')+resultMoney(Math.abs(value));}
function renderPlanResult(){
 const plan=state.plan;
 if(!plan){app.innerHTML=`${flowHeader()}<main class="dashboard">${friendlyEmptyMarkup()}</main>`;bindFlowHeader();document.querySelector('#result-settings').onclick=()=>navigate('settings');return;}

 const cart=state.baskets.find(b=>b.id===state.recommended),budget=Math.round(plan.settings.budget*100),over=cart?Math.max(0,cart.total_kopecks-budget):null;
 app.innerHTML=`${flowHeader()}<main class="result-page"><div class="page-head"><div><div class="eyebrow">ВАШ ПЛАН ПИТАНИЯ</div><h1>Меню готово</h1><p>${plan.days} дней · ${plan.settings.participants?.length>1?'Семейный план':goalLabels[plan.settings.goal]} · ${num(plan.settings.target.kcal)} ккал в день</p></div><span class="badge ${plan.status==='saved'?'':'amber'}" id="plan-status">${plan.status==='saved'?'План сохранён':'Черновик'}</span></div>${familySummary()}<div id="page-error" class="error" role="alert"></div><div class="result-columns"><section id="result-menu" aria-label="Меню по дням"><p class="small muted">Цена блюда: стоимость ингредиентов${state.dish_price_store?' по предложениям '+esc(state.dish_price_store):''}. Закупка учитывает целые упаковки и запасы. Цены демонстрационные.</p>${Array.from({length:plan.days},(_,day)=>{const items=plan.items.filter(i=>i.day===day),date=new Date(plan.start_date+'T12:00:00');date.setDate(date.getDate()+day);return `<section class="panel result-day" data-result-day="${day}"><div class="summary-block-head"><h2>День ${day+1}</h2><span class="small muted">${dateLabel(date.toISOString())}</span></div>${items.map(i=>{const recipe=state.recipes.find(r=>r.id===i.recipe_id);return `<article class="result-meal" data-item-id="${i.id}"><div><span class="eyebrow">${labelMeal(recipe.meal)}</span><h3>${esc(recipe.name)}</h3><p class="small muted">${num(i.nutrition.kcal)} ккал${i.portions?' на всех':''} · ${recipe.minutes} мин</p>${i.portions?`<p class="small muted family-portions">${i.portions.map(p=>`${esc(p.name)}: ${num(p.nutrition.kcal)} ккал`).join(' · ')}</p>`:''}</div><div class="meal-price"><strong>${i.estimated_cost_kopecks===null?'Нет цены':resultMoney(i.estimated_cost_kopecks)}</strong><button class="secondary" data-result-replace="${i.id}">Заменить</button></div></article>`;}).join('')}</section>`;}).join('')}</section><aside><section class="panel result-cart ${over?'cart-over':''}" id="result-cart"><div class="eyebrow">КОРЗИНА</div><h2>Закупка по плану</h2><div class="result-total" id="cart-total">${cart?resultMoney(cart.total_kopecks):'Нет полной корзины'}</div><p class="small muted">${cart?esc(cart.name)+' · целые упаковки':'Для части продуктов нет предложений'}</p><div class="budget-comparison"><span>Бюджет</span><strong id="result-budget">${resultMoney(budget)}</strong></div><p class="budget-state ${over?'over':''}" ${over?'role="alert"':''} id="budget-state">${cart?(over?'Превышение на '+resultMoney(over):'В бюджете. Осталось '+resultMoney(budget-cart.total_kopecks)):'Полную сумму пока нельзя сравнить с бюджетом'}</p><div class="button-stack"><button id="save-plan" ${plan.status==='saved'?'disabled':''}>${plan.status==='saved'?'План сохранён':'Сохранить план'}</button><button class="secondary" id="result-settings">Изменить настройки</button></div><div class="separator"></div><button class="link" id="result-shopping">Список продуктов →</button><button class="link" id="result-stores">Сравнить магазины →</button><p class="small muted">${cart?.oldest_price?'Дата цен: '+dateLabel(cart.oldest_price):''}</p></section></aside></div></main>`;
 bindFlowHeader();document.querySelector('#result-settings').onclick=()=>navigate('settings');document.querySelector('#result-shopping').onclick=()=>navigate('shopping');document.querySelector('#result-stores').onclick=()=>navigate('baskets');
 app.querySelectorAll('[data-result-replace]').forEach(b=>b.onclick=()=>openReplacement(b.dataset.resultReplace));
 document.querySelector('#save-plan').onclick=e=>busy(e.target,async()=>{const y=scrollY;state=await api('/plan/save','POST',{plan_id:plan.id,expected_revision:plan.revision});render();window.scrollTo(0,y);toast('План сохранён');});
}
async function openReplacement(itemId){
 currentItem=state.plan.items.find(i=>i.id===itemId);if(!currentItem)return;
 const recipe=state.recipes.find(r=>r.id===currentItem.recipe_id);
 dialog.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">ЗАМЕНА БЛЮДА</div><h2 id="recipe-title">${esc(recipe.name)}</h2></div><button class="secondary" id="close-replacement" aria-label="Закрыть замену">×</button></div><div id="dialog-error" class="error" role="alert"></div><p class="small muted">Учтены аллергии, предпочтения, калорийность и повторы.</p><section id="alternatives" aria-live="polite">Рассчитываем варианты…</section>`;
 document.querySelector('#close-replacement').onclick=()=>dialog.close();dialog.showModal();
 try{await loadReplacementAlternatives();}catch(e){errorBox(e,'#dialog-error');}
}
async function loadReplacementAlternatives(){
 const itemId=currentItem.id,request=++alternativeRequest;
 const preview=await api('/alternatives?item_id='+encodeURIComponent(itemId));
 if(!dialog.open||currentItem.id!==itemId||request!==alternativeRequest)return;
 const el=document.querySelector('#alternatives');
 el.innerHTML=preview.alternatives.length?`<p class="small muted">Изменение цены всей корзины после замены. Порция сохраняет калорийность приёма пищи.</p><div class="replacement-list">${preview.alternatives.map(r=>`<article class="replacement-card"><div><h3>${esc(r.name)}</h3><span class="small muted">${num(r.planned_nutrition.kcal)} ккал · ${r.minutes} мин</span></div><div class="replacement-price"><strong class="${r.cart_delta_kopecks>0?'price-up':r.cart_delta_kopecks<0?'price-down':'muted'}">${deltaLabel(r.cart_delta_kopecks)}</strong><button data-choose-replacement="${r.id}">Выбрать</button></div></article>`).join('')}</div>`:'<div class="note amber">Нет подходящих альтернатив. Текущее блюдо сохранено.</div>';
 el.querySelectorAll('[data-choose-replacement]').forEach(button=>button.onclick=async()=>{
  if(dialog.dataset.applying==='true')return;
  dialog.dataset.applying='true';dialog.querySelectorAll('button').forEach(b=>b.disabled=true);
  dialog.oncancel=e=>e.preventDefault();const y=scrollY;
  try{state=await api('/replace','POST',{item_id:itemId,recipe_id:button.dataset.chooseReplacement,expected_revision:preview.plan_revision});dialog.close();render();window.scrollTo(0,y);document.querySelector(`[data-result-replace="${itemId}"], [data-replace="${itemId}"]`)?.focus({preventScroll:true});toast('Блюдо заменено. Корзина пересчитана.');}
  catch(e){errorBox(e,'#dialog-error');if(e.status===409){const refresh=document.createElement('button');refresh.className='secondary';refresh.textContent='Обновить результат';refresh.onclick=async()=>{state=await api('/state');dialog.close();navigate('result');};document.querySelector('#dialog-error').append(document.createElement('br'),refresh);}}
  finally{delete dialog.dataset.applying;dialog.oncancel=null;dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}
 });
}
